  "claims": [
    {
      "text": "In principle, a certification trade mark can be used to distinguish goods certified as to their origin from goods not so certified.",
      "quotes": [
        {
          "ref": "TMA1995/s169",
          "quote": "A certification trade mark is a sign used, or intended to be used, to distinguish goods or services: (a) dealt with or provided in the course of trade; and (b) certified by a person (owner of the certification trade mark), or by another person approved by that person, in relation to quality, accuracy or some other characteristic, including (in the case of goods) origin, material or mode of manufacture; from other goods or services dealt with or provided in the course of trade but not so certified."
        }
      ],
      "authority": "legislation"
    },
    {
      "text": "The Manual describes a geographical indication as identifying goods whose quality, reputation or other characteristic is essentially attributable to their geographical origin.",
      "quotes": [
        {
          "ref": "TMM/Part46/4/4/6/1",
          "quote": "a sign that identifies the goods as originating in a country, or in a region or locality in that country, where a given quality, reputation or other characteristic of the goods is essentially attributable to their geographical origin."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "These passages support certification of geographical origin as a possible function of a certification trade mark, but do not expressly answer whether, on what conditions, or with what scope of protection a geographical indication can be registered as one in Australia.",
      "quotes": [],
      "authority": "none"
    }
  ],
